from sympy import symbols, sympify, limit, simplify, diff, factorial, oo, nan

n = symbols("n", integer=True, positive=True)
x = symbols("x")

def seq_limit(data):
    L = limit(data[0], n, oo)
    if L == oo or L == -oo:
        print(f"  a_n -> {L}, so the sequence diverges")
    elif L == nan:
        print("  no single limit, so the sequence diverges")
    else:
        print(f"  a_n -> {L}, so the sequence converges to {L}")

def geometric(data):
    a, r, start = data
    first = a * r**start
    print(f"  first term ({a})({r})^{start} = {first}, ratio {r}")
    if abs(r) >= 1:
        print(f"  |r| = {abs(r)} >= 1, so it diverges")
    else:
        print(f"  |r| = {abs(r)} < 1, so the sum is first/(1 - r) = {first / (1 - r)}")

def pseries(data):
    p = data[0]
    if p > 1:
        print(f"  p = {p} > 1, so the p-series converges")
    elif p > 0:
        print(f"  0 < p = {p} <= 1, so the p-series diverges")
    else:
        print(f"  p = {p} <= 0: the terms don't go to 0, so it diverges")

def ratio(data):
    q = simplify(data[0].subs(n, n + 1) / data[0])
    L = limit(q, n, oo)
    print(f"  |a_(n+1)/a_n| = {q} -> L = {L}")
    if L < 1:
        print("  L < 1, so it converges absolutely")
    elif L > 1:
        print("  L > 1, so it diverges")
    else:
        print("  L = 1, so the ratio test says nothing")

def radius(data):
    c, a = data
    L = limit(simplify(c.subs(n, n + 1) / c), n, oo)
    if L == 0:
        print("  |c_(n+1)/c_n| -> 0, so R = oo: it converges for every x")
    elif L == oo:
        print(f"  |c_(n+1)/c_n| -> oo, so R = 0: it converges only at x = {a}")
    else:
        print(f"  |c_(n+1)/c_n| -> {L}, so R = {1 / L}: it converges for {a - 1 / L} < x < {a + 1 / L}")

def taylor(data):
    f, a, degree = data
    for k in range(degree + 1):
        value = diff(f, x, k).subs(x, a)
        print(f"  k = {k}: f^(k)({a}) = {value}, c_{k} = {value / factorial(k)}")

methods = {"limit": seq_limit, "geometric": geometric, "pseries": pseries,
           "ratio": ratio, "radius": radius, "taylor": taylor}
problems = ["limit (4*n**2-n)/(2*n**2+3)", "geometric 3 1/4 1", "ratio 5**n/factorial(n)",
            "pseries 3/2", "radius 1/(n*3**n) 0", "taylor sqrt(x) 16 2",
            "limit n**2/(n+1)", "geometric 1 -3/2 0", "ratio 1/n**2", "radius 1/factorial(n) 0"]
for i in range(len(problems)):
    parts = problems[i].split()
    data = [sympify(t, locals={"n": n, "x": x}) for t in parts[1:]]
    print(f"Problem {i + 1}: {problems[i]}")
    methods[parts[0]](data)

