from sympy import symbols, sympify, limit, simplify, diff, factorial, oo

n = symbols("n", integer=True, positive=True)
x = symbols("x")

def decreasing(b):
    return all(b.subs(n, k + 1) <= b.subs(n, k) for k in range(1, 101))

def classify(data):
    b, p = data
    far = limit(b, n, oo)
    if far != 0:
        print(f"  1. the sizes go to {far}, not 0, so it diverges")
        return
    print("  1. the sizes go to 0")
    c = limit(b * n**p, n, oo)
    if c != oo and p > 1:
        print(f"  2. against 1/n^({p}), c = {c}: the sizes converge, so it converges absolutely")
    elif c == 0 or p > 1:
        print(f"  2. against 1/n^({p}), c = {c}: no decision, pick p from the dominant terms")
    elif decreasing(b):
        print(f"  2. against 1/n^({p}), c = {c}: the sizes diverge")
        print("  3. the sizes decrease to 0, so it converges conditionally")
    else:
        print(f"  2. against 1/n^({p}), c = {c}: the sizes diverge")
        print("  3. the sizes don't decrease, so these tests decide nothing")

def interval(data):
    c, a, p = data
    R = 1 / limit(simplify(c.subs(n, n + 1) / c), n, oo)
    size = simplify(c * R**n)
    print(f"  R = {R}, and at x = {a - R} and x = {a + R} the terms have size {size}")
    k = limit(size * n**p, n, oo)
    if limit(size, n, oo) != 0:
        print(f"  the sizes don't go to 0, so neither end: ({a - R}, {a + R})")
    elif k != oo and p > 1:
        print(f"  against 1/n^({p}), c = {k}: both ends converge, [{a - R}, {a + R}]")
    elif k == 0 or p > 1:
        print(f"  against 1/n^({p}), c = {k}: no decision, pick p from the dominant terms")
    elif decreasing(size):
        print(f"  x = {a + R} diverges, x = {a - R} alternates and converges: [{a - R}, {a + R})")
    else:
        print(f"  x = {a + R} diverges, and no decision at x = {a - R}")

def remainder(data):
    p, tol = data
    m = 1
    while m**(1 - p) / (p - 1) > tol:
        m = m + 1
    print(f"  R_n <= n^(1 - p)/(p - 1) = {m**(1 - p) / (p - 1)} <= {tol} first at n = {m}")

def alternating(data):
    b, tol = data
    m = 1
    while b.subs(n, m + 1) > tol:
        m = m + 1
    s = sum((-1)**(k - 1) * b.subs(n, k) for k in range(1, m + 1))
    print(f"  b_(n+1) = {b.subs(n, m + 1)} <= {tol} first at n = {m}, and s_{m} = {float(s):.6f}")
    sign, side = ("+", "small") if m % 2 == 0 else ("-", "big")
    print(f"  the next term is {sign}b_{m + 1}, so s_{m} is too {side}")

def terms(data):
    f, a, point, M, tol = data
    m = 0
    while M * abs(point - a)**(m + 1) / factorial(m + 1) > tol:
        m = m + 1
    bound = M * abs(point - a)**(m + 1) / factorial(m + 1)
    T = sum(diff(f, x, k).subs(x, a) / factorial(k) * (point - a)**k for k in range(m + 1))
    print(f"  the bound is at most {float(tol):g} first at n = {m}: {float(bound):.2e}")
    print(f"  T_{m} = {float(T):.10f}, true error {abs(float(f.subs(x, point) - T)):.2e}")

methods = {"classify": classify, "interval": interval, "remainder": remainder, "alternating": alternating, "terms": terms}
problems = ["classify (n+1)/(n**2+2) 1", "interval 1/(n*2**n) 1 1", "remainder 3 1/5000", "alternating 1/(n*2**n) 1/1000",
            "terms cos(x) 0 3/10 1 10**-8", "classify n/(n+1) 0", "classify 1/n**2 2", "interval 1/n**2 0 2", "interval n 0 0"]
for i in range(len(problems)):
    parts = problems[i].split()
    data = [sympify(t, locals={"n": n, "x": x}) for t in parts[1:]]
    print(f"Problem {i + 1}: {problems[i]}")
    methods[parts[0]](data)

